import rawCore from '../data/manifest.generated.json';
import type { DifficultyLevel, ManifestClip } from './types';

/**
 * Clip manifest, in two layers.
 *
 * `MANIFEST` is a small core bundled into the JS bundle, so a first run has a
 * working corpus with zero network calls and keeps working offline.
 *
 * `loadFullManifest()` pulls the full curated corpus from `/manifest.json`,
 * generated by `scripts/harvest.py` (650 clips, ~84 MB of streamed audio, 175 KB
 * of JSON and ~33 KB gzipped). Keeping it out of the bundle holds first load at
 * ~193 kB while making every tier 130 clips deep with an even spread of sentence
 * lengths.
 *
 * Entries carry `(config, split, rowIdx)` rather than an audio URL, because the
 * CDN signs its URLs with an expiry and a stored URL goes stale.
 */

/**
 * Mean FLAC size in KB for a given word count.
 *
 * Measured from all 5,323 local LibriSpeech clips rather than assumed. A flat
 * average is badly wrong per tier: a 3-word utterance is ~45 KB because of the
 * fixed per-utterance silence and container overhead, while a 30-word one is
 * ~191 KB, so tier 1 and tier 5 differ by more than 4x. The curve was measured
 * on the `clean` splits and applied to `other` as well, which uses the same
 * 16 kHz mono encoding and reads at a similar rate.
 */
const KB_BY_WORDS: readonly number[] = [
  0, 41.6, 41.6, 45.1, 45.2, 50.2, 53.7, 57.1, 61.3, 67.7, 71.2, 78.0, 82.0,
  89.7, 94.9, 98.5, 104.4, 114.0, 118.2, 127.4, 129.1, 138.7, 140.8, 146.1,
  152.3, 156.2, 162.5, 168.3, 174.6, 186.8, 190.7,
];

/** Estimated stored size of one clip, from its transcript length. */
export function clipBytes(wordCount: number): number {
  const index = Math.max(0, Math.min(KB_BY_WORDS.length - 1, Math.round(wordCount)));
  return (KB_BY_WORDS[index] ?? 100) * 1024;
}

/**
 * Measured FLAC-to-Opus ratio for this corpus (47 KB FLAC became 7.7 KB of
 * WebM/Opus on a real clip). Used for size estimates, and asserted in the suite
 * so the offline capacity claims cannot drift away from reality.
 */
export const OPUS_COMPRESSION_RATIO = 6.1;

/** Estimated stored size of a set of clips once compacted to Opus. */
export function estimateCompactBytes(clips: readonly { wordCount: number }[]): number {
  return estimateClipBytes(clips) / OPUS_COMPRESSION_RATIO;
}

/** Estimated stored size of a set of clips. */
export function estimateClipBytes(clips: readonly { wordCount: number }[]): number {
  return clips.reduce((sum, clip) => sum + clipBytes(clip.wordCount), 0);
}

/** Human-readable label for a clip's LibriSpeech directory. */
function splitLabelFor(config: 'clean' | 'other', split: 'test' | 'validation'): ManifestClip['splitLabel'] {
  if (split === 'test') return config === 'clean' ? 'test-clean' : 'test-other';
  return config === 'clean' ? 'dev-clean' : 'dev-other';
}

/** Coerces arbitrary JSON into clips, dropping anything malformed. */
export function validateManifest(input: unknown): ManifestClip[] {
  if (!Array.isArray(input)) return [];
  const clips: ManifestClip[] = [];
  const seen = new Set<string>();
  for (const entry of input) {
    if (typeof entry !== 'object' || entry === null) continue;
    const candidate = entry as Record<string, unknown>;
    const config = candidate.config;
    const split = candidate.split;
    if (config !== 'clean' && config !== 'other') continue;
    if (split !== 'test' && split !== 'validation') continue;
    const level = Number(candidate.level);
    if (!Number.isInteger(level) || level < 1 || level > 5) continue;
    const id = candidate.id;
    const text = candidate.text;
    const rowIdx = Number(candidate.rowIdx);
    if (typeof id !== 'string' || typeof text !== 'string' || !Number.isFinite(rowIdx)) continue;
    if (seen.has(id)) continue;
    seen.add(id);

    clips.push({
      id,
      text,
      speakerId: String(candidate.speakerId ?? ''),
      chapterId: String(candidate.chapterId ?? ''),
      config,
      split,
      splitLabel: splitLabelFor(config, split),
      rowIdx,
      level: level as DifficultyLevel,
      wordCount: Number(candidate.wordCount) || text.trim().split(/\s+/).length,
      speakerMinutes: Number.isFinite(Number(candidate.speakerMinutes))
        ? Number(candidate.speakerMinutes)
        : 0,
      index: Number(candidate.index) || 0,
    });
  }
  return clips;
}

/** The bundled core corpus. Always available, never fetched. */
export const MANIFEST: readonly ManifestClip[] = validateManifest(rawCore as unknown);

/** Clip count available with no network access at all. */
export const CORE_MANIFEST_SIZE = MANIFEST.length;

let fullManifestPromise: Promise<ManifestClip[]> | null = null;

/**
 * Fetches the full curated corpus, memoised for the page lifetime.
 *
 * Failure is not an error condition — the core corpus runs the whole app — so a
 * missing, stale or truncated manifest simply means a smaller pool.
 */
export function loadFullManifest(): Promise<ManifestClip[]> {
  if (fullManifestPromise) return fullManifestPromise;

  fullManifestPromise = (async () => {
    try {
      // Deliberately no `cache: 'force-cache'`. That option means "use the
      // cached copy even if it is stale", which defeats the server's
      // `max-age=0` revalidation and pins every client to whatever corpus
      // existed the first time they loaded the app - so a redeploy would never
      // reach them. The default respects HTTP: revalidate against the edge,
      // which holds the manifest for a year and answers with a cheap 304.
      const response = await fetch('/manifest.json');
      if (!response.ok) return [];
      const clips = validateManifest((await response.json()) as unknown);
      // Never let a truncated response shrink the corpus below the bundled core.
      return clips.length > MANIFEST.length ? clips : [];
    } catch {
      return [];
    }
  })();

  return fullManifestPromise;
}

export function manifestForLevel(level: DifficultyLevel): ManifestClip[] {
  return MANIFEST.filter((clip) => clip.level === level);
}

export function formatBytes(bytes: number): string {
  if (bytes >= 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`;
  if (bytes >= 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  if (bytes >= 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${bytes} B`;
}
